import{_ as n,W as o,s as d,u as c,ah as l,I as i,w as s,Z as a,A as p}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const k=JSON.parse('{"title":"如何在 Linux 中压缩和解压缩文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中压缩和解压缩文件 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中压缩和解压缩文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中压缩和解压缩文件 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180324 How To Compress And Decompress Files In Linux","title":"如何在 Linux 中压缩和解压缩文件","tag":"201809"},"relativePath":"201809/20180324 How To Compress And Decompress Files In Linux.md","filePath":"[post].md"}'),h={name:"201809/20180324 How To Compress And Decompress Files In Linux.md"};function g(u,e,r,b,x,v){const t=o("Link");return c(),d("div",null,[e[15]||(e[15]=l(`<h1 id="如何在-linux-中压缩和解压缩文件" tabindex="-1">如何在 Linux 中压缩和解压缩文件 <a class="header-anchor" href="#如何在-linux-中压缩和解压缩文件" aria-label="Permalink to 如何在 Linux 中压缩和解压缩文件">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/compress-720x340.jpg" alt=""></p><p>当在备份重要文件和通过网络发送大文件的时候，对文件进行压缩非常有用。请注意，压缩一个已经压缩过的文件会增加额外开销，因此你将会得到一个更大一些的文件。所以，请不要压缩已经压缩过的文件。在 GNU/Linux 中，有许多程序可以用来压缩和解压缩文件。在这篇教程中，我们仅学习其中两个应用程序。</p><p>在类 Unix 系统中，最常见的用来压缩文件的程序是：</p><ol><li>gzip</li><li>bzip2</li></ol><h3 id="_1-使用-gzip-程序来压缩和解压缩文件" tabindex="-1">1. 使用 gzip 程序来压缩和解压缩文件 <a class="header-anchor" href="#_1-使用-gzip-程序来压缩和解压缩文件" aria-label="Permalink to 1. 使用 gzip 程序来压缩和解压缩文件">​</a></h3><p><code>gzip</code> 是一个使用 Lempel-Ziv 编码（LZ77）算法来压缩和解压缩文件的实用工具。</p><h4 id="_1-1-压缩文件" tabindex="-1">1.1 压缩文件 <a class="header-anchor" href="#_1-1-压缩文件" aria-label="Permalink to 1.1 压缩文件">​</a></h4><p>如果要压缩一个名为 <code>ostechnix.txt</code> 的文件，使之成为 gzip 格式的压缩文件，那么只需运行如下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip ostechnix.txt</span></span></code></pre></div><p>上面的命令运行结束之后，将会出现一个名为 <code>ostechnix.txt.gz</code> 的 gzip 格式压缩文件，代替了原始的 <code>ostechnix.txt</code> 文件。</p><p><code>gzip</code> 命令还可以有其他用法。一个有趣的例子是，我们可以将一个特定命令的输出通过管道传递，然后作为 <code>gzip</code> 程序的输入来创建一个压缩文件。看下面的命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ls -l Downloads/ | gzip &gt; ostechnix.txt.gz</span></span></code></pre></div><p>上面的命令将会创建一个 gzip 格式的压缩文件，文件的内容为 <code>Downloads</code>　目录的目录项。</p><h4 id="_1-2-压缩文件并将输出写到新文件中-不覆盖原始文件" tabindex="-1">1.2 压缩文件并将输出写到新文件中（不覆盖原始文件） <a class="header-anchor" href="#_1-2-压缩文件并将输出写到新文件中-不覆盖原始文件" aria-label="Permalink to 1.2 压缩文件并将输出写到新文件中（不覆盖原始文件）">​</a></h4><p>默认情况下，<code>gzip</code> 程序会压缩给定文件，并以压缩文件替代原始文件。但是，你也可以保留原始文件，并将输出写到标准输出。比如，下面这个命令将会压缩 <code>ostechnix.txt</code> 文件，并将输出写入文件 <code>output.txt.gz</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip -c ostechnix.txt &gt; output.txt.gz</span></span></code></pre></div><p>类似地，要解压缩一个 <code>gzip</code> 格式的压缩文件并指定输出文件的文件名，只需运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip -c -d output.txt.gz &gt; ostechnix1.txt</span></span></code></pre></div><p>上面的命令将会解压缩 <code>output.txt.gz</code> 文件，并将输出写入到文件 <code>ostechnix1.txt</code> 中。在上面两个例子中，原始文件均不会被删除。</p><h4 id="_1-3-解压缩文件" tabindex="-1">1.3 解压缩文件 <a class="header-anchor" href="#_1-3-解压缩文件" aria-label="Permalink to 1.3 解压缩文件">​</a></h4><p>如果要解压缩 <code>ostechnix.txt.gz</code> 文件，并以原始未压缩版本的文件来代替它，那么只需运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip -d ostechnix.txt.gz</span></span></code></pre></div><p>我们也可以使用 <code>gunzip</code> 程序来解压缩文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gunzip ostechnix.txt.gz</span></span></code></pre></div><h4 id="_1-4-在不解压缩的情况下查看压缩文件的内容" tabindex="-1">1.4 在不解压缩的情况下查看压缩文件的内容 <a class="header-anchor" href="#_1-4-在不解压缩的情况下查看压缩文件的内容" aria-label="Permalink to 1.4 在不解压缩的情况下查看压缩文件的内容">​</a></h4><p>如果你想在不解压缩的情况下，使用 <code>gzip</code> 程序查看压缩文件的内容，那么可以像下面这样使用 <code>-c</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gunzip -c ostechnix1.txt.gz</span></span></code></pre></div><p>或者，你也可以像下面这样使用 <code>zcat</code> 程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ zcat ostechnix.txt.gz</span></span></code></pre></div><p>你也可以通过管道将输出传递给 <code>less</code> 命令，从而一页一页的来查看输出，就像下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gunzip -c ostechnix1.txt.gz | less</span></span>
<span class="line"><span>$ zcat ostechnix.txt.gz | less</span></span></code></pre></div><p>另外，<code>zless</code> 程序也能够实现和上面的管道同样的功能。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ zless ostechnix1.txt.gz</span></span></code></pre></div><h4 id="_1-5-使用-gzip-压缩文件并指定压缩级别" tabindex="-1">1.5 使用 gzip 压缩文件并指定压缩级别 <a class="header-anchor" href="#_1-5-使用-gzip-压缩文件并指定压缩级别" aria-label="Permalink to 1.5 使用 gzip 压缩文件并指定压缩级别">​</a></h4><p><code>gzip</code> 的另外一个显著优点是支持压缩级别。它支持下面给出的 3 个压缩级别：</p><ul><li><strong>1</strong> – 最快 (最差)</li><li><strong>9</strong> – 最慢 (最好)</li><li><strong>6</strong> – 默认级别</li></ul><p>要压缩名为 <code>ostechnix.txt</code> 的文件，使之成为“最好”压缩级别的 gzip 压缩文件，可以运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip -9 ostechnix.txt</span></span></code></pre></div><h4 id="_1-6-连接多个压缩文件" tabindex="-1">1.6 连接多个压缩文件 <a class="header-anchor" href="#_1-6-连接多个压缩文件" aria-label="Permalink to 1.6 连接多个压缩文件">​</a></h4><p>我们也可以把多个需要压缩的文件压缩到同一个文件中。如何实现呢？看下面这个例子。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gzip -c ostechnix1.txt &gt; output.txt.gz</span></span>
<span class="line"><span>$ gzip -c ostechnix2.txt &gt;&gt; output.txt.gz</span></span></code></pre></div><p>上面的两个命令将会压缩文件 <code>ostechnix1.txt</code> 和 <code>ostechnix2.txt</code>，并将输出保存到一个文件 <code>output.txt.gz</code> 中。</p><p>你可以通过下面其中任何一个命令，在不解压缩的情况下，查看两个文件 <code>ostechnix1.txt</code> 和 <code>ostechnix2.txt</code> 的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ gunzip -c output.txt.gz</span></span>
<span class="line"><span>$ gunzip -c output.txt</span></span>
<span class="line"><span>$ zcat output.txt.gz</span></span>
<span class="line"><span>$ zcat output.txt</span></span></code></pre></div><p>如果你想了解关于 <code>gzip</code> 的更多细节，请参阅它的 man 手册。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ man gzip</span></span></code></pre></div><h3 id="_2-使用-bzip2-程序来压缩和解压缩文件" tabindex="-1">2. 使用 bzip2 程序来压缩和解压缩文件 <a class="header-anchor" href="#_2-使用-bzip2-程序来压缩和解压缩文件" aria-label="Permalink to 2. 使用 bzip2 程序来压缩和解压缩文件">​</a></h3><p><code>bzip2</code> 和 <code>gzip</code> 非常类似，但是 <code>bzip2</code> 使用的是 Burrows-Wheeler 块排序压缩算法，并使用<ruby>哈夫曼<rt>Huffman</rt></ruby>编码。使用 <code>bzip2</code> 压缩的文件以 “.bz2” 扩展结尾。</p><p>正如我上面所说的， <code>bzip2</code> 的用法和 <code>gzip</code> 几乎完全相同。只需在上面的例子中将 <code>gzip</code> 换成 <code>bzip2</code>，将 <code>gunzip</code> 换成 <code>bunzip2</code>，将 <code>zcat</code> 换成 <code>bzcat</code> 即可。</p><p>要使用 <code>bzip2</code> 压缩一个文件，并以压缩后的文件取而代之，只需运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bzip2 ostechnix.txt</span></span></code></pre></div><p>如果你不想替换原始文件，那么可以使用 <code>-c</code> 选项，并把输出写入到新文件中。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bzip2 -c ostechnix.txt &gt; output.txt.bz2</span></span></code></pre></div><p>如果要解压缩文件，则运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bzip2 -d ostechnix.txt.bz2</span></span></code></pre></div><p>或者，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bunzip2 ostechnix.txt.bz2</span></span></code></pre></div><p>如果要在不解压缩的情况下查看一个压缩文件的内容，则运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bunzip2 -c ostechnix.txt.bz2</span></span></code></pre></div><p>或者，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ bzcat ostechnix.txt.bz2</span></span></code></pre></div><p>如果你想了解关于 <code>bzip2</code> 的更多细节，请参阅它的 man 手册。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ man bzip2</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>在这篇教程中，我们学习了 <code>gzip</code> 和 <code>bzip2</code> 程序是什么，并通过 GNU/Linux 下的一些例子学习了如何使用它们来压缩和解压缩文件。接下来，我们将要学习如何在 Linux 中将文件和目录归档。</p><p>干杯！</p><hr>`,68)),i("p",null,[e[1]||(e[1]=s("via: ")),a(t,{href:"https://www.ostechnix.com/how-to-compress-and-decompress-files-in-linux/"},{default:p(()=>e[0]||(e[0]=[s("https://www.ostechnix.com/how-to-compress-and-decompress-files-in-linux/")])),_:1})]),i("p",null,[e[6]||(e[6]=s("作者：")),a(t,{href:"https://www.ostechnix.com/author/sk/"},{default:p(()=>e[2]||(e[2]=[s("SK")])),_:1}),e[7]||(e[7]=s(" 选题：")),a(t,{href:"https://github.com/lujun9972"},{default:p(()=>e[3]||(e[3]=[s("lujun9972")])),_:1}),e[8]||(e[8]=s(" 译者：")),a(t,{href:"https://github.com/ucasFL"},{default:p(()=>e[4]||(e[4]=[s("ucasFL")])),_:1}),e[9]||(e[9]=s(" 校对：")),a(t,{href:"https://github.com/wxy"},{default:p(()=>e[5]||(e[5]=[s("wxy")])),_:1})]),i("p",null,[e[12]||(e[12]=s("本文由 ")),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>e[10]||(e[10]=[s("LCTT")])),_:1}),e[13]||(e[13]=s(" 原创编译，")),a(t,{href:"https://linux.cn/"},{default:p(()=>e[11]||(e[11]=[s("Linux中国")])),_:1}),e[14]||(e[14]=s(" 荣誉推出"))])])}const C=n(h,[["render",g]]);export{k as __pageData,C as default};
